"""Real JEE Main questions — Chemistry Unit 13: Purification and Characterisation of Organic Compounds. Our own
solutions; chk recomputes every number — Dumas (ideal gas, minus aqueous tension), Kjeldahl (acid neutralised),
Carius and combustion (mass fractions from molar masses computed from the formula), R_f, empirical formulae.
Statement and matching items are checked against a fact table of methods."""
import re
from common import new_registry, pick, verify
from chemkit import stmt, pickset
P, add = new_registry()
AM = {'C': 12, 'H': 1, 'N': 14, 'O': 16, 'S': 32, 'Cl': 35.5, 'Br': 80, 'I': 127, 'Ag': 108, 'Ba': 137}
def mm(f):
    return sum(AM[e] * (int(n) if n else 1) for e, n in re.findall(r'([A-Z][a-z]?)(\d*)', f))
def frac(el, f): return AM[el] * dict((e, int(n) if n else 1) for e, n in re.findall(r'([A-Z][a-z]?)(\d*)', f))[el] / mm(f)
def dumas(w, mL, T, P, aq=0, R=0.0821): return (P - aq) / 760 * mL / 1000 / (R * T) * 28 / w * 100
def kjel(w, mL, M, basic=2): return basic * M * mL / 1000 * 14 / w * 100
def carius(w, wppt, ppt, el): return wppt * frac(el, ppt) / w * 100
# purification facts: method → what it separates
METHOD = {'simple': 'liquids with a large difference in boiling points (chloroform + aniline)', 'fractional': 'liquids with close boiling points (crude oil fractions, diesel + petrol)',
          'reduced': 'liquids that decompose at their boiling point (glycerol from spent-lye)', 'steam': 'steam-volatile, water-immiscible substances (aniline + water, essential oils)'}
STO = ['Both Statement I and Statement II are true', 'Both Statement I and Statement II are false', 'Statement I is true but Statement II is false', 'Statement I is false but Statement II is true']
STC = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct']

