# ---------------- purification and chromatography ----------------
MATCH_D = dict(simple='chloroform + aniline', fractional='crude oil fractions', reduced='glycerol from spent-lye', steam='aniline + water')
def match(order_methods, items, opts):
    return pick(opts, ', '.join(f'{k}-{items[MATCH_D[m]]}' for k, m in zip('ABCD', order_methods)))
